cd /tmp/vally-eval-trial-weBqPM && cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public static class Checkout
{
    public static decimal CalculatePayableTotal(string customerTier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        Assert.Equal(95.00m, Checkout.CalculatePayableTotal("Gold", 100.00m));
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

